#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){const char* path=argc>1?argv[1]:"data/w33_pass1848_syndrome_columns.txt";vector<uint64_t> c(240);ifstream in(path);for(auto&x:c)in>>x;vector<uint64_t> p; p.reserve(28680);for(int i=0;i<240;i++)for(int j=i+1;j<240;j++)p.push_back(c[i]^c[j]);sort(p.begin(),p.end());unordered_set<uint64_t> pset;pset.reserve(p.size()*2);map<int,uint64_t> ph;for(size_t i=0;i<p.size();){size_t j=i+1;while(j<p.size()&&p[j]==p[i])j++;ph[j-i]++;pset.insert(p[i]);i=j;}
vector<uint64_t> q;q.reserve(134810340ULL);for(int i=0;i<240;i++)for(int j=i+1;j<240;j++){auto a=c[i]^c[j];for(int k=j+1;k<240;k++){auto b=a^c[k];for(int l=k+1;l<240;l++)q.push_back(b^c[l]);}}sort(q.begin(),q.end());map<int,uint64_t> qh;uint64_t qgroups=0,overlap_pair=0,zero_mult=0,maxq=0;for(size_t i=0;i<q.size();){size_t j=i+1;while(j<q.size()&&q[j]==q[i])j++;auto m=j-i;qh[m]++;qgroups++;maxq=max<uint64_t>(maxq,m);if(pset.count(q[i]))overlap_pair++;if(q[i]==0)zero_mult=m;i=j;}
auto printmap=[](map<int,uint64_t>&h){bool f=0;cout<<"{";for(auto[m,n]:h){if(f)cout<<",";f=1;cout<<"\""<<m<<"\":"<<n;}cout<<"}";};cout<<"{\"pair_records\":"<<p.size()<<",\"pair_distinct\":"<<pset.size()<<",\"pair_hist\":";printmap(ph);cout<<",\"weight4_records\":"<<q.size()<<",\"weight4_distinct\":"<<qgroups<<",\"weight4_hist\":";printmap(qh);cout<<",\"weight4_pair_syndrome_overlap\":"<<overlap_pair<<",\"weight4_zero_multiplicity\":"<<zero_mult<<",\"weight4_max_multiplicity\":"<<maxq<<"}\n";}
